 names.forEach((name,i)=>{this.s.agents.push({id:'a'+i,name,kind:i%5,color:colors[i],hub:i<5?'hill':i===5?'garden':i===6?'workshop':'pond',x:100+i%5*150,y:0,action:null,reason:'Taking a look around.',needs:{hunger:20+i*6,fatigue:15+i*4,boredom:30+i*5,loneliness:20+i*7},traits:{O:20+i*10,C:85-i*8,E:15+i*11,A:80-i*7,N:25+i*8},taste:{color:['green','blue','purple'][i%3],novelty:(20+i*10)/100},inventory:{food:7,fibre:i===6?6:0,cloth:i===6?2:0,dye:i===6?2:0,timber:i===5?6:0,clay:0,water:0,energy:0},skill:20+i*7,relations:{},lastBuy:-999,lastSocial:-999});});
 for(const a of this.s.agents)for(const b of this.s.agents)if(a!==b)a.relations[b.id]={familiarity:15,trust:55,affection:a.hub===b.hub?35:15};
