 craft(a,recipe,contract=null){const r=recipes[recipe];if(!r)return false;if(this.s.agents.filter(b=>b.action?.station===r.station).length>=this.s.infrastructure.workshop)return false;if(this.s.stations[r.station].condition<15)return false;if(!this.canPay(a,r.inputs))return false;this.move(a,'workshop');this.pay(a,r.inputs);return this.start(a,'craft',r.duration,contract?'Fulfilling a paid promise.':'Making something to use or offer.',{recipe,station:r.station,toX:170+['loom','tailor','bench','kiln'].indexOf(r.station)*165,contract:contract?.id,color:contract?this.agent(contract.from).taste.color:a.taste.color})}
 makeItem(a,type,color){const quality=a.skill>=65?'fine':a.skill>=35?'sound':'rough';const item={id:this.id('i'),type,owners:[a.id],holder:a.id,access:'private',condition:100,quality,color,maker:a.id,acquiredAt:this.s.time};this.s.items.push(item);return item}
 offerHat(a){const hats=this.s.items.filter(x=>x.type==='hat'&&x.owners[0]===a.id&&x.holder===a.id);const item=hats.find(x=>this.s.time-(x.acquiredAt||0)>120&&(hats.length>1||a.inventory.food<3||x.color!==a.taste.color));if(!item||this.s.contracts.some(c=>c.status==='proposed'&&c.terms.item===item.id))return;const buyers=this.s.agents.filter(b=>b!==a&&b.inventory.food>=3&&this.s.time-b.lastBuy>120&&!this.s.items.some(i=>i.type==='hat'&&i.holder===b.id));const buyer=buyers.sort((b,c)=>this.hatValue(c,item)-this.hatValue(b,item))[0];if(buyer&&this.hatValue(buyer,item)>3)this.propose('sale',a.id,buyer.id,{item:item.id,price:3})}
