 if(act.type==='chat'){const b=this.agent(act.partner);if(b&&b.hub===a.hub){const compatibility=1-Math.abs(a.traits.E-b.traits.E)/100;n.loneliness=clamp(n.loneliness-35);b.needs.loneliness=clamp(b.needs.loneliness-20);n.boredom=clamp(n.boredom-15);this.relation(a,b,0,1+compatibility*3);this.relation(b,a,0,1+compatibility*3);this.log(`${a.name} and ${b.name} spent time together.`)}}
 if(act.type==='craft'&&!act.maintenance){let item;if(act.recipe==='cloth')a.inventory.cloth++;else item=this.makeItem(a,act.recipe,act.color);a.skill=clamp(a.skill+2);n.boredom=clamp(n.boredom-30);n.fatigue=clamp(n.fatigue+8);this.s.stations[act.station].condition=clamp(this.s.stations[act.station].condition-2);this.log(`${a.name} made ${act.recipe==='cloth'?'cloth': 'a '+item.quality+' '+act.recipe}.`);const c=this.s.contracts.find(c=>c.id===act.contract);if(c?.status==='active'&&item){const buyer=this.agent(c.from);item.owners=[buyer.id];item.holder=buyer.id;a.inventory.food+=c.escrow;c.escrow=0;c.status='fulfilled';this.relation(buyer,a,6,3);this.log(`${c.id} fulfilled: ownership and payment transferred.`)}}
